// ---------------------------------------------------------------------------
// AUTO-GENERATED by Claude Code
// Purpose: the one pick-from-a-list input of tool forms (render._choice_input), single or
//          multiple (tool_forms.picker_for). The only difference is data-multiple: several
//          picks tick / untick and keep the list open; one pick replaces the last and closes it.
//          Whether the list has a search box depends only on its length (FormField.search).
// Markup it drives (all rendered by Reflex, found by data- attributes):
//   [data-choice]          the wrapper; data-multiple="true" | "false"; .is-open while the list shows
//   [data-choice-box]      the box (focusable): the chips and a caret; click / Enter / Space / ↓ open
//   [data-choice-chips]    inside the box: the picks as chips (icon + name + ×); this script owns it
//   [data-choice-value]    the hidden input the form submits: picked values joined by "," ("" = any)
//   [data-choice-list]     the list: [data-choice-search]? then [data-choice-options], .choice-option
//                          buttons with data-value, data-label, data-icon ("" = no icon)
// Keys: arrows move, Enter (Space on the box) picks, Backspace removes the last pick, Escape /
// Tab / a click outside closes. One set of listeners on document, so inputs Reflex mounts later
// just work.
// ---------------------------------------------------------------------------
(() => {
  const parts = (el) => {
    const root = el.closest?.("[data-choice]");
    if (!root) return null;
    return {
      root,
      multiple: root.dataset.multiple !== "false",
      box: root.querySelector("[data-choice-box]"),
      chips: root.querySelector("[data-choice-chips]"),
      value: root.querySelector("[data-choice-value]"),
      list: root.querySelector("[data-choice-list]"),
      search: root.querySelector("[data-choice-search]"),
      scroller: root.querySelector("[data-choice-options]"),
    };
  };
  const options = (p) => [...p.scroller.querySelectorAll(".choice-option")];
  const visible = (p) => options(p).filter((o) => !o.hidden);
  const active = (p) => p.scroller.querySelector(".choice-option.is-active");
  const picked = (p) => p.value.value.split(",").filter(Boolean);
  const isOpen = (p) => p.root.classList.contains("is-open");

  // the chips (in pick order) and the ✓ marks, from the hidden value; "any" when nothing is picked
  const render = (p) => {
    const values = picked(p);
    const byValue = new Map(options(p).map((o) => [o.dataset.value, o]));
    options(p).forEach((o) => o.classList.toggle("is-picked", values.includes(o.dataset.value)));
    const chips = values.map((value) => {
      const o = byValue.get(value);
      const chip = document.createElement("span");
      chip.className = "choice-chip";
      if (o?.dataset.icon) {
        const img = document.createElement("img");
        img.src = o.dataset.icon;
        img.alt = "";
        img.className = "char-icon";
        chip.append(img);
      }
      const label = document.createElement("span");
      label.textContent = o ? o.dataset.label : value;
      const remove = document.createElement("span");
      remove.className = "choice-remove";
      remove.dataset.choiceRemove = value;
      remove.title = `Remove ${label.textContent}`;
      remove.textContent = "×";
      chip.append(label, remove);
      return chip;
    });
    if (!chips.length) {
      const none = document.createElement("span");
      none.className = "dim";
      none.textContent = "any";
      chips.push(none);
    }
    p.chips.replaceChildren(...chips);
    if (isOpen(p)) place(p); // the box may have grown a line
  };

  const setPicked = (p, values) => {
    p.value.value = values.join(",");
    render(p);
  };
  // the one place single and multiple differ
  const choose = (p, option) => {
    const value = option.dataset.value;
    const values = picked(p);
    if (!p.multiple) {
      setPicked(p, [value]);
      return close(p, true);
    }
    setPicked(p, values.includes(value) ? values.filter((v) => v !== value) : [...values, value]);
    setActive(p, option);
  };

  // scroll only the list (never scrollIntoView: that can scroll the tab around it, which closes the list)
  const setActive = (p, option) => {
    options(p).forEach((o) => o.classList.toggle("is-active", o === option));
    if (!option) return;
    const top = option.offsetTop;
    const bottom = top + option.offsetHeight;
    const s = p.scroller;
    if (top < s.scrollTop) s.scrollTop = top;
    else if (bottom > s.scrollTop + s.clientHeight) s.scrollTop = bottom - s.clientHeight;
  };
  const filter = (p) => {
    const wanted = (p.search?.value || "").trim().toLowerCase();
    options(p).forEach((o) => {
      const hay = `${o.dataset.label} ${o.dataset.value}`.toLowerCase();
      o.hidden = wanted !== "" && !hay.includes(wanted);
    });
    const shown = visible(p);
    setActive(p, (!wanted && shown.find((o) => o.classList.contains("is-picked"))) || shown[0] || null);
  };

  // position: fixed under (or above) the box, so a scrolling parent (a result tab) can't clip it
  const place = (p) => {
    const box = p.box.getBoundingClientRect();
    const below = window.innerHeight - box.bottom;
    p.list.style.left = `${Math.min(box.left, window.innerWidth - 250)}px`;
    p.list.style.minWidth = `${Math.max(box.width, 220)}px`;
    if (below < 260 && box.top > below) {
      p.list.style.top = "";
      p.list.style.bottom = `${window.innerHeight - box.top + 2}px`;
      p.list.style.maxHeight = `${Math.min(340, box.top - 8)}px`;
    } else {
      p.list.style.bottom = "";
      p.list.style.top = `${box.bottom + 2}px`;
      p.list.style.maxHeight = `${Math.min(340, below - 8)}px`;
    }
  };

  const open = (p) => {
    document.querySelectorAll("[data-choice].is-open").forEach((r) => r !== p.root && close(parts(r), false));
    p.root.classList.add("is-open");
    if (p.search) p.search.value = "";
    filter(p);
    place(p);
    (p.search || p.box).focus();
  };
  const close = (p, refocus) => {
    p.root.classList.remove("is-open");
    if (refocus) p.box.focus();
  };

  // an input Reflex just mounted: show what its hidden value holds
  const init = (root) => {
    root.querySelectorAll?.("[data-choice]:not([data-choice-ready])").forEach((r) => {
      r.dataset.choiceReady = "1";
      render(parts(r));
    });
  };
  new MutationObserver((changes) => changes.forEach((c) => c.addedNodes.forEach((n) => n.nodeType === 1 && init(n.parentNode || n))))
    .observe(document.documentElement, { childList: true, subtree: true });
  document.addEventListener("DOMContentLoaded", () => init(document));

  // mousedown, not click, with preventDefault: focus stays where it is (the search box)
  document.addEventListener("mousedown", (event) => {
    const p = parts(event.target);
    if (!p) {
      document.querySelectorAll("[data-choice].is-open").forEach((r) => close(parts(r), false));
      return;
    }
    if (event.target === p.search) return; // the browser places the caret
    event.preventDefault();
    const remove = event.target.closest("[data-choice-remove]");
    const option = event.target.closest(".choice-option");
    if (remove) {
      setPicked(p, picked(p).filter((v) => v !== remove.dataset.choiceRemove));
      if (!isOpen(p)) p.box.focus();
    } else if (option) choose(p, option);
    else if (event.target.closest("[data-choice-box]")) isOpen(p) ? close(p, true) : open(p);
  });
  // the field sits in a <label>: its click would "click" the first button inside (an option)
  document.addEventListener("click", (event) => {
    const p = parts(event.target);
    if (p && event.target !== p.search) event.preventDefault();
  });
  // focus left the input (Tab, a click elsewhere): close
  document.addEventListener("focusout", (event) => {
    const p = parts(event.target);
    if (p && isOpen(p) && !p.root.contains(event.relatedTarget)) close(p, false);
  });
  document.addEventListener("input", (event) => {
    if (event.target.matches?.("[data-choice-search]")) filter(parts(event.target));
  });

  document.addEventListener(
    "keydown",
    (event) => {
      if (!event.target.matches?.("[data-choice-box], [data-choice-search]")) return;
      const p = parts(event.target);
      const onBox = event.target === p.box;
      if (event.key === "Backspace" && (onBox || p.search.value === "") && picked(p).length) {
        event.preventDefault();
        setPicked(p, picked(p).slice(0, -1));
      } else if (!isOpen(p)) {
        if (onBox && ["ArrowDown", "Enter", " "].includes(event.key)) {
          event.preventDefault();
          open(p);
        }
      } else if (event.key === "ArrowDown" || event.key === "ArrowUp") {
        event.preventDefault();
        const shown = visible(p);
        const at = shown.indexOf(active(p));
        const next = event.key === "ArrowDown" ? Math.min(at + 1, shown.length - 1) : Math.max(at - 1, 0);
        setActive(p, shown[next] || null);
      } else if (event.key === "Enter" || (event.key === " " && onBox)) {
        // the list is open: Enter picks the active option; it never runs the form
        event.preventDefault();
        event.stopPropagation();
        if (active(p)) choose(p, active(p));
      } else if (event.key === "Escape") {
        // capture phase + stop: Esc closes this list, not the floating view around it (panes.js)
        event.preventDefault();
        event.stopPropagation();
        close(p, true);
      }
    },
    true,
  );

  // an open list is in the wrong place once the page scrolls or resizes: close it
  const closeAll = (event) => {
    if (event?.target?.closest?.("[data-choice-list]")) return; // scrolling the list itself
    document.querySelectorAll("[data-choice].is-open").forEach((r) => r.classList.remove("is-open"));
  };
  window.addEventListener("scroll", closeAll, true);
  window.addEventListener("resize", closeAll);
})();
